// The recovered menu enumerates contiguous _saveNNN.dat files from slot zero.
export function nextSaveName(names){const used=new Set(names.map(n=>n.toLowerCase()));for(let slot=0;slot<1000;slot++){const name=`_save${String(slot).padStart(3,'0')}.dat`;if(!used.has(name))return name.toUpperCase();}throw Error('All 1,000 native save slots are occupied.');}
export function validateNativeSave(name,bytes){if(!/^_?save\d{3}\.dat$/i.test(name))throw Error('Choose an original SAVE000.DAT or browser _save000.dat file.');if(bytes.length<12||String.fromCharCode(...bytes.slice(0,4))!=='FORM'||String.fromCharCode(...bytes.slice(8,12))!=='SCEN')throw Error('The selected file is not a native Dune II save.');const size=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength).getUint32(4,false);if(size+8!==bytes.length)throw Error('The native save is truncated or has an invalid FORM length.');return true;}
